public class NaiveZ {
    public int[] zArray(String s) {
        int L = s.length();
        int[] z = new int[L];
        for (int i = 1; i < L; i++) {
            int k = 0;
            while (i + k < L && s.charAt(k) == s.charAt(i + k)) {
                k++;
            }
            z[i] = k;
        }
        return z;
    }

    public static void main(String[] args) {
        int[] z = new NaiveZ().zArray("aabxaab");
        for (int v : z) System.out.print(v + " ");
        System.out.println();
    }
}

