import java.util.ArrayList;
import java.util.List;

public class ZSearch {
    public int[] zArray(String s) {
        int L = s.length();
        int[] z = new int[L];
        int l = 0, r = 0;
        for (int i = 1; i < L; i++) {
            if (i < r) {
                z[i] = Math.min(r - i, z[i - l]);
            }
            while (i + z[i] < L && s.charAt(z[i]) == s.charAt(i + z[i])) {
                z[i]++;
            }
            if (i + z[i] > r) {
                l = i;
                r = i + z[i];
            }
        }
        return z;
    }

    public List<Integer> search(String t, String p) {
        List<Integer> result = new ArrayList<>();
        int m = p.length();
        String s = p + "\u0001" + t;
        int[] z = zArray(s);
        for (int i = m + 1; i < s.length(); i++) {
            if (z[i] == m) {
                result.add(i - (m + 1));
            }
        }
        return result;
    }

    public static void main(String[] args) {
        System.out.println(new ZSearch().search("aabxaabxcaabxaabxay", "aabx"));
    }
}

