def z_array(s: str) -> list[int]:
    L = len(s)
    z = [0] * L
    l = r = 0
    for i in range(1, L):
        if i < r:
            z[i] = min(r - i, z[i - l])
        while i + z[i] < L and s[z[i]] == s[i + z[i]]:
            z[i] += 1
        if i + z[i] > r:
            l, r = i, i + z[i]
    return z


def search(t: str, p: str) -> list[int]:
    m = len(p)
    s = p + "\x01" + t
    z = z_array(s)
    return [i - (m + 1) for i in range(m + 1, len(s)) if z[i] == m]


if __name__ == "__main__":
    print(search("aabxaabxcaabxaabxay", "aabx"))

